const serviceDefinitions=[['renewals','Renewal reminders','45, 30, 15, 7, 3, 1 days before expiry and on expiry. Health/life follow-ups after expiry.'],['leads','Quote & lead follow-ups','Gentle follow-ups; an integrated service must stop these when a customer replies.'],['wishes','Birthday & anniversary wishes','Personal wishes for customers with recorded dates.'],['thanks','Policy-issued thank-you','Policy details and copy after confirmed policy mapping.'],['review','Old-customer policy review','A review invitation for customers who did not renew.'],['touch','Stay in touch','A useful monthly message, with consent and opt-out handling.'],['video','Branded videos','Personalised media requires your media library and rendering service.'],['priority','Priority help','Requires a connected support service.']];
const navigationGo=go;
go=function(id){if(id!==current){category='All';filter='All';query='';fromDate='';toDate='';dateWindow='This month';contactTab='All';viewMode=id==='leads'?'kanban':'table'}navigationGo(id)};
notifications=function(){let due=db.bookings.filter(b=>!b.renewed&&inDateWindow(b.renewal,'This month')).length,newLeads=db.leads.filter(l=>normalStage(l.status)==='New').length;modal('Workspace updates',`<div class="activity">${I('renew')}<div><strong>${due} renewals this month</strong><small>From your workspace records</small></div></div><div class="activity">${I('leads')}<div><strong>${newLeads} new leads</strong><small>In your local pipeline</small></div></div>${db.activity.slice(0,8).map(a=>`<div class="activity">${I('check')}<div><strong>${esc(a.text)}</strong><small>${esc(a.date)}</small></div></div>`).join('')}`)};
assistant=function(){return heading('AI ASSISTANT','Your WhatsApp assistant','Renewals, follow-ups, wishes and thank-you notes in your name.','<span class="badge">NOT CONNECTED</span>')+`<section class="hero"><div class="eyebrow">YOUR CUSTOMERS. YOUR RELATIONSHIPS.</div><h2>Timely messages.<br>A more personal business.</h2><p>Choose your service preferences and preview message drafts. Automatic delivery, replies, trials and subscriptions are unavailable until your own WhatsApp and billing services are connected.</p>${btn('Connection requirements',"go('integrations')",'lock')}${btn('Preview business summary','assistantSummary()','spark')}</section><div class="record-grid">${serviceDefinitions.map(([key,title,description])=>`<article class="card pad"><div class="service-icon">${I(key==='renewals'?'renew':key==='wishes'?'gift':'spark')}</div><h3>${title}</h3><p class="paneltext">${description}</p><label class="preference"><input type="checkbox" ${workspace.services[key]?'checked':''} onchange="workspace.services['${key}']=this.checked;saveWorkspace()"> Save as preferred service</label><p><span class="badge">Delivery inactive</span></p>${btn('Preview draft',`serviceDraft('${key}')`,'file')}</article>`).join('')}</div><section class="card pad" style="margin-top:24px"><h2>Who can receive messages?</h2><p class="paneltext">Only customers whose records and consent you manage. This workspace never sends messages automatically. Use Preview draft to review text and explicitly open WhatsApp.</p></section>`}
function assistantSummary(){modal('Business summary',`<p>${db.bookings.length} policy records<br>${db.leads.length} leads<br>${db.contacts.length} contacts<br>${rupee(total())} recorded premium</p><p>This summary is calculated from this browser’s records. It is not a response from a live AI model.</p>`)}
function serviceDraft(key){let c=db.contacts[0],b=db.bookings[0],l=db.leads[0],name=c?.name||'customer';let drafts={renewals:b?`Hi ${b.name}, your ${b.product} policy is due on ${b.renewal}. Would you like help reviewing your cover and renewing it?`:'Add a policy with an expiry date before drafting a renewal reminder.',leads:l?`Hi ${l.name}, following up on your ${l.product} enquiry. Would you like to discuss the next steps?`:'Add a lead to prepare a follow-up.',wishes:`Hi ${name}, wishing you a wonderful birthday and a happy, healthy year ahead! — ${workspace.profile.name}`,thanks:b?`Hi ${b.name}, thank you for trusting us with your insurance needs. Your policy details: ${b.policyNumber||'confirm policy number before sharing'}. — ${workspace.profile.name}`:'Add a confirmed policy before drafting a thank-you.',review:`Hi ${name}, would you like a free review of your current insurance cover before renewal? — ${workspace.profile.name}`,touch:`Hi ${name}, a quick reminder to keep your policy documents and nominee details up to date. Let me know if you need any help. — ${workspace.profile.name}`};if(!drafts[key])return modal('Service not connected','<p>'+missingService+'</p>');draftMessage(drafts[key])}
function integrationsPage(){return heading('SERVICE CONNECTIONS','Integration requirements','Website login does not provide the original application’s backend or APIs.')+`<section class="card"><table><thead><tr><th>Service</th><th>Required to go live</th><th>Status</th></tr></thead><tbody>${[['Accounts / OTP','Your auth provider, verified domain, session handling and user database'],['Policy approval & sync','Authenticated workflow API, approver roles, insurer documents and database'],['AI document extraction','Server-side vision/OCR endpoint and model credentials'],['WhatsApp assistant','Approved WhatsApp provider, consent, templates, webhooks and scheduled worker'],['Payments / points','Authoritative commission ledger and verified payout events'],['Referral attribution','Public onboarding route and referral tracking database'],['Marketing assets / videos','Licensed media library, storage and personalised rendering service'],['Multi-user records','User-owned database, access controls and document storage']].map(([s,r])=>`<tr><td>${s}</td><td class="wrap">${r}</td><td><span class="badge">Not connected</span></td></tr>`).join('')}</tbody></table></section><section class="card pad" style="margin-top:22px"><h2>What works on this device</h2><p class="paneltext">Product forms, locally stored uploads, saved leads, contact conversion, filters, reports, rate comparisons, earnings calculations and quote documents. No action in this workspace creates a record in Incremint or an insurer’s system.</p></section>`}
function settingsPage(){let p=workspace.profile;return heading('WORKSPACE','Profile & data','Manage your advisor details, links and browser data.')+`<section class="card pad"><h2>Advisor profile</h2><form onsubmit="event.preventDefault();saveProfile(this)"><div class="formgrid">${fieldHTML(F('name','Advisor name','text',true),p.name)}${fieldHTML(F('phone','Business mobile','tel'),p.phone)}${fieldHTML(F('email','Email','email'),p.email)}${fieldHTML(F('agentCode','Agent code'),p.agentCode)}${fieldHTML(F('referralLink','Your working referral / onboarding URL','url'),p.referralLink)}${fieldHTML(F('publicWebsite','Your published website URL','url'),p.publicWebsite)}${fieldHTML(F('bio','About you','textarea'),p.bio)}</div><div class="modalfoot"><button class="primary">Save profile</button></div></form></section><div class="split" style="margin-top:22px"><section class="card pad"><h2>Backup & restore</h2><p class="paneltext">A JSON backup includes your records and document references. Uploaded document files are stored separately in this browser and are not inside the backup.</p><div class="actions">${btn('Export backup','exportBackup()','download')}<label class="upload-button">Restore backup<input type="file" accept=".json" onchange="restoreWorkspaceBackup(this.files[0])"></label></div></section><section class="card pad"><h2>Import verified records</h2><p class="paneltext">Use your own authorised rate cards, payout statement and partner roster.</p><div class="actions">${btn('Rates',"importDataDialog('rates')",'file')}${btn('Payouts',"importDataDialog('payouts')",'wallet')}${btn('Partners',"importDataDialog('network')",'users')}</div></section></div>${btn('Service connections',"go('integrations')",'lock')}`}
settings=function(){closeModal();go('settings')};
function saveProfile(form){let p=Object.fromEntries(new FormData(form));for(const key of ['referralLink','publicWebsite'])if(p[key]&&!/^https:\/\//i.test(p[key]))return toast('Website links must use HTTPS');if(p.phone&&!validPhone(p.phone))return toast('Enter a valid business mobile');workspace.profile={...workspace.profile,...p};saveWorkspace();render();toast('Profile saved')}
function exportBackup(){fileDownload('sigma0nine-backup.json',JSON.stringify({version:2,exportedAt:new Date().toISOString(),records:db,workspace,quoteDraft},null,2),'application/json')}
let pendingBackup;
async function restoreWorkspaceBackup(file){try{if(!file||file.size>10*1024*1024)throw Error('Choose a backup under 10 MB');let b=JSON.parse(await file.text());let records=b.records||b;if(!['bookings','leads','contacts','network','activity'].every(k=>Array.isArray(records[k])))throw Error('Invalid backup');for(let r of [...records.bookings,...records.leads,...records.contacts])if(typeof r.id!=='string'||typeof r.name!=='string')throw Error('Invalid record');pendingBackup={records,workspace:b.workspace,quoteDraft:b.quoteDraft};modal('Restore this backup?',`<p>Restoring replaces the records in this browser. Download a current backup first if you need to retain them.</p><p>${records.bookings.length} bookings · ${records.leads.length} leads · ${records.contacts.length} contacts</p><div class="modalfoot">${btn('Cancel','closeModal()')}${btn('Replace workspace records','confirmWorkspaceRestore()','check',true)}</div>`)}catch(e){toast(e.message)}}
function confirmWorkspaceRestore(){try{if(!pendingBackup)return;let b=pendingBackup;if(b.workspace){for(let key of ['quotes','payouts','rates','assets','prospects','pinned'])if(!Array.isArray(b.workspace[key]))throw Error('Invalid workspace section: '+key)}db=b.records;if(b.workspace)Object.assign(workspace,b.workspace);if(b.quoteDraft)quoteDraft=b.quoteDraft;save();saveWorkspace();saveQuoteDraft();pendingBackup=null;closeModal();render();toast('Workspace restored')}catch(e){toast(e.message)}}
function pinnedToggle(){if(workspace.pinned.includes(current))workspace.pinned=workspace.pinned.filter(p=>p!==current);else workspace.pinned.push(current);saveWorkspace();render()}
render=function(){legacyRender();let brand=document.querySelector('.workspace');if(brand)brand.insertAdjacentHTML('afterend',`<button class="sidebar-booking primary" onclick="mapBooking()">${I('plus')} Add My Booking</button><button class="pin-page" onclick="pinnedToggle()">${workspace.pinned.includes(current)?'★ Pinned':'☆ Pin this page'}</button>${workspace.pinned.length?`<div class="pinned-pages">${workspace.pinned.map(p=>`<button onclick="go('${p}')">${esc(nav.find(n=>n[0]===p)?.[2]||p)}</button>`).join('')}</div>`:''}`);let profile=document.querySelector('.sidebarbottom');if(profile)profile.innerHTML=`<div class="avatar">${esc(initials(workspace.profile.name||'Partner'))}</div><div><strong>${esc(workspace.profile.name||'Partner')}</strong><small>Browser workspace</small></div><button class="quiet" aria-label="Workspace settings" onclick="settings()">${I('dots')}</button>`;if(current==='marketing')loadAssetPreviews();};
function helpPage(){let articles=[['How do I create a health lead?','Choose Health in Refer & earn. Select base plan, super top-up or port; enter insured members, cover amount, diseases and add-ons. Port cases include previous insurer, premium, expiry and claim history. Review before saving.'],['How do I map an existing policy?','Add My Booking opens Map My Lead. Upload a policy copy, enter verified customer details and save an approval request. This workspace stores the request locally; no approver is connected.'],['How are Motor and Travel leads different?','Motor leads collect the case type, RC for renewal, customer details and vehicle cover. Travel collects destination type, traveller details, documents and trip dates.'],['How do Group Health, Group PA, Home and Fire leads work?','Each has its own multi-step form. Company or property details, required cover, prior policy, relevant documents and a final review are kept with the lead.'],['How can I track leads?','Use the six pipeline stages: New, Quote given, Booked, Policy issued, Won & Mapped, Lost. The stage is a manual workspace record, not insurer confirmation.'],['How do I create health comparison and Niva quotes?','Open Health Quote or Niva Quote. Enter customer/member data and verified premium inputs. Preview, save the quote and create a local lead. Print / Save PDF opens your browser print dialog. Niva comparisons include five tenures, eight components and auto-negative discounts.'],['Where are my documents stored?','Uploads are saved in IndexedDB in this browser. JSON backups store document references, not the actual uploaded files. Export important files separately.'],['Can the assistant send WhatsApp messages automatically?','No. A provider, customer consent, templates, webhooks and a scheduler are not connected. The current tools let you review a draft and explicitly open WhatsApp.'],['How do I update mobile or email?','Use Workspace settings for advisor details. Use My contacts → Edit for customer details. Changes are stored in this browser.'],['Why are payouts and rates empty?','The original service’s private data is not available through website login. Import your authorised payout records and rate cards in Workspace settings.'],['How do I share my website or invite partners?','Configure a working public website and referral URL in Workspace settings. Exporting an advisor HTML page does not automatically host it or attribute referrals.']];let found=articles.filter(a=>a.join(' ').toLowerCase().includes(query.toLowerCase()));return heading('HOW-TO GUIDES','Help guide','Search for a clear step-by-step answer.')+`<div class="toolbar">${inlineSearch('Search health lead, payout, mobile, WhatsApp…')}</div><section class="card" id="results">${found.map(([q,a])=>`<details class="help-item"><summary>${q}</summary><p>${a}</p></details>`).join('')||emptyCard('No matching guides','Try another keyword.')}</section>`}
help=helpPage;
const mediaCategories=['All','Health','Life','Festival','General','Motor','Mutual Fund','Stock','My Card'];
marketing=function(){return heading('MARKETING KIT','Marketing kit','Personalise your licensed artwork, manage videos and export your advisor page.',btn('Add media','mediaUploadForm()','plus',true))+pillTabs(['Posters','Videos','My Website'],marketingTab,'setMarketingTab')+(marketingTab==='My Website'?websiteEditor():`${pillTabs(mediaCategories,category,'setMediaCategory')}<div class="toolbar">${inlineSearch('Search media…')}</div><div id="results">${marketingResults()}</div>`)};
function setMarketingTab(v){marketingTab=v;render()}
function setMediaCategory(v){category=v;render()}
function mediaRows(){return workspace.assets.filter(a=>(marketingTab==='Videos'?a.kind==='video':a.kind==='image')&&(category==='All'||a.category===category)&&a.title.toLowerCase().includes(query.toLowerCase()))}
function marketingResults(){let rows=mediaRows();return rows.length?`<div class="poster-grid">${rows.map(a=>`<article class="card"><div class="asset-preview" data-asset="${a.id}">${I(a.kind==='video'?'plane':'file')}</div><div class="posterbottom"><div><strong>${esc(a.title)}</strong><p class="subtle">${esc(a.category)}</p></div>${btn(a.kind==='image'?'Personalise':'Download',a.kind==='image'?`personaliseAsset('${a.id}')`:`downloadAttachment('${a.file.id}')`,'download')}</div></article>`).join('')}</div>`:'<section class="card">'+emptyCard('Your media library is empty','Upload artwork or video you are authorised to personalise. Original Incremint media is not bundled.',btn('Add media','mediaUploadForm()','plus',true))+'</section>'}
function mediaUploadForm(){modal('Add licensed media',`<form onsubmit="event.preventDefault();saveMedia(this)"><div class="formgrid">${fieldHTML(F('title','Title','text',true))}${fieldHTML(F('category','Category','select',true,mediaCategories.filter(x=>x!=='All')))}<label class="field full">Artwork or video *<input type="file" name="asset" accept="image/png,image/jpeg,image/webp,video/mp4,video/webm" required></label><label class="field full">Caption<textarea name="caption" rows="3"></textarea></label></div><div class="modalfoot"><button class="primary">Add to library</button></div></form>`)}
async function saveMedia(form){try{let d=Object.fromEntries(new FormData(form)),f=form.elements.asset.files[0];if(!f||!['image/png','image/jpeg','image/webp','video/mp4','video/webm'].includes(f.type))throw Error('Choose a supported image or video');let meta=await persistFile(f,true);workspace.assets.unshift({id:uid('ASSET'),title:d.title,category:d.category,caption:d.caption,file:meta,kind:f.type.startsWith('video/')?'video':'image'});saveWorkspace();closeModal();render();toast('Media stored in this browser')}catch(e){toast(e.message)}}
let assetURLs=new Map();
async function loadAssetPreviews(){for(let a of mediaRows()){let el=document.querySelector(`[data-asset="${a.id}"]`);if(!el)continue;try{let f=await readAttachment(a.file.id);if(!f)continue;if(!assetURLs.has(a.id))assetURLs.set(a.id,URL.createObjectURL(f));if(a.kind==='image')el.innerHTML=`<img src="${assetURLs.get(a.id)}" alt="${esc(a.title)}">`;else el.innerHTML=`<video controls preload="metadata" src="${assetURLs.get(a.id)}"></video>`}catch{el.textContent='Media unavailable in this browser'}}}
function personaliseAsset(id){let a=workspace.assets.find(a=>a.id===id),p=workspace.profile;modal('Personalise artwork',`<form onsubmit="event.preventDefault();exportPersonalised('${id}',this)"><div class="formgrid">${fieldHTML(F('name','Advisor name','text',true),p.name)}${fieldHTML(F('phone','Business mobile','tel'),p.phone)}<label class="field full">Format<select name="format"><option value="image/jpeg">JPG</option><option value="image/png">PNG</option></select></label></div><div class="modalfoot"><button class="primary">Save personalised image</button></div></form><p>${esc(a.caption||'')}</p><div class="actions">${btn('Copy caption',`copyMediaCaption('${id}')`,'copy')}</div>`)}
function copyMediaCaption(id){let a=workspace.assets.find(a=>a.id===id);copyText(`${a.caption||a.title}\n${workspace.profile.name} ${workspace.profile.phone||''}${workspace.profile.publicWebsite?'\n'+workspace.profile.publicWebsite:''}`)}
async function exportPersonalised(id,form){try{let a=workspace.assets.find(a=>a.id===id),f=await readAttachment(a.file.id),data=new FormData(form);if(!f)throw Error('Image file is unavailable');let url=URL.createObjectURL(f),im=new Image();try{im.src=url;await im.decode();let width=Math.min(im.naturalWidth,2000),height=Math.round(im.naturalHeight*width/im.naturalWidth),footer=Math.round(width*.12),canvas=document.createElement('canvas');canvas.width=width;canvas.height=height+footer;let ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height+footer);ctx.drawImage(im,0,0,width,height);ctx.fillStyle='#071c48';ctx.fillRect(0,height,width,footer);ctx.fillStyle='#fff';ctx.font=`bold ${Math.max(14,width*.027)}px Arial`;ctx.fillText(String(data.get('name')),width*.04,height+footer*.42,width*.6);ctx.font=`${Math.max(12,width*.021)}px Arial`;ctx.fillStyle='#9bceff';ctx.fillText(String(data.get('phone')),width*.04,height+footer*.76,width*.6);ctx.fillStyle='#41a9ff';ctx.font=`bold ${Math.max(14,width*.025)}px Arial`;ctx.fillText('Sigma0Nine',width*.73,height+footer*.58,width*.23);let blob=await new Promise(r=>canvas.toBlob(r,data.get('format'),.94));if(!blob)throw Error('Image export failed');fileDownload('sigma0nine-'+a.title.replace(/[^a-z0-9]/gi,'-')+(data.get('format')==='image/png'?'.png':'.jpg'),blob,data.get('format'));toast('Personalised image downloaded')}finally{URL.revokeObjectURL(url)}}catch(e){toast(e.message)}}
function websiteEditor(){return `<section class="card pad"><h2>My website</h2><p class="paneltext">Use your saved profile to export a standalone advisor page. Hosting and public lead capture require a backend.</p><h3>${esc(workspace.profile.name)}</h3><p>${esc(workspace.profile.bio||'Add your advisor biography in Workspace settings.')}</p><div class="actions">${btn('Edit profile','settings()','contact')}${btn('Export advisor HTML','exportAdvisorWebsite()','download',true)}${workspace.profile.publicWebsite?btn('Copy website link','copyText(workspace.profile.publicWebsite)','copy'):''}</div></section>`}
function exportAdvisorWebsite(){let p=workspace.profile,html=`<!doctype html><html lang="en"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(p.name)} — Sigma0Nine</title><style>body{margin:0;background:#f1f6ff;color:#12355f;font:18px/1.8 Arial}main{max-width:800px;margin:10vh auto;padding:45px;background:white;border-radius:24px}h1{color:#071c48}small{color:#087fff}a{color:#087fff}</style><main><small>SIGMA0NINE · YOUR INSURANCE BUSINESS, SIMPLIFIED.</small><h1>${esc(p.name)}</h1><p>${esc(p.bio||'Your insurance partner.')}</p><p>${esc(p.phone||'')}<br>${esc(p.email||'')}</p>${p.referralLink&&/^https:\/\//.test(p.referralLink)?`<a href="${esc(p.referralLink)}">Enquire about insurance</a>`:'<p>Contact the advisor directly to discuss your requirements.</p>'}</main></html>`;fileDownload('sigma0nine-advisor.html',html,'text/html')}
